diff --git a/src/realtime/realtime-voice.spec.ts b/src/realtime/realtime-voice.spec.ts
new file mode 100644
index 0000000..4df1f63
--- /dev/null
+++ b/src/realtime/realtime-voice.spec.ts
@@ -0,0 +1,50 @@
+import * as fs from 'fs';
+import * as path from 'path';
+
+jest.mock('ws', () => {
+  const instances: any[] = [];
+  function Mock(this: any, url: string, opts: any) {
+    this.url = url;
+    this.opts = opts;
+    this.handlers = {};
+    this.sent = [];
+    this.on = (e: string, h: any) => { this.handlers[e] = h; };
+    this.send = (m: string) => this.sent.push(JSON.parse(m));
+    instances.push(this);
+  }
+  Mock.OPEN = 1;
+  (Mock as any).instances = instances;
+  return { __esModule: true, default: Mock };
+});
+
+import WebSocket from 'ws';
+import { RealtimeVoiceService, OPENAI_REALTIME_URL } from './realtime-voice.service';
+
+describe('realtime GA + model migration', () => {
+  it('uses GA realtime', async () => {
+    expect(OPENAI_REALTIME_URL).toContain('model=gpt-realtime-2.1');
+    const svc = new RealtimeVoiceService('k');
+    const audio = jest.fn();
+    const p = svc.connectToOpenAI(audio);
+    const ws = (WebSocket as any).instances[0];
+    expect(ws.opts.headers['OpenAI-Beta']).toBeUndefined();
+    ws.handlers.open();
+    await p;
+    expect(ws.sent[0].session.type).toBe('realtime');
+    expect(ws.sent[0].session.audio.output.voice).toBe('alloy');
+    ws.handlers.message(Buffer.from(JSON.stringify({ type: 'response.output_audio.delta', delta: 'x' })));
+    expect(audio).toHaveBeenCalledWith('x');
+  });
+
+  it('no retired chat models or max_tokens in OpenAI calls', () => {
+    const walk = (d: string): string[] =>
+      fs.readdirSync(d, { withFileTypes: true }).flatMap((e) =>
+        e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
+    const files = walk(path.join(__dirname, '..')).filter((f) => f.endsWith('.ts') && !f.endsWith('.spec.ts'));
+    for (const f of files) {
+      const s = fs.readFileSync(f, 'utf8');
+      expect(s).not.toMatch(/gpt-4o|chatgpt-4o/);
+      expect(s).not.toMatch(/\bmax_tokens\b/);
+    }
+  });
+});
